  // core spawned with a tank's hit points, so a rifle round taking one man's
  // worth of damage would have needed six to ten hits to kill him.
  s[b + U_HP] = isArmour(i) ? Math.imul(60 + nextBelow(rng, 40), ONE) : RIFLE_HP;
